    float edge=side*7;foreach(float dz in new[]{-5f,5f})Box("Kính an toàn / "+name,new Vector3(edge,2,z+dz),new Vector3(.14f,4,7),glass);Box("Khung cửa / "+name,new Vector3(edge,3.65f,z),new Vector3(.2f,.3f,3),steel);foreach(float dz in new[]{-1.5f,1.5f})Box("Trụ cửa",new Vector3(edge,1.9f,z+dz),new Vector3(.22f,3.8f,.22f),steel);Sign(name,new Vector3(edge-side*.2f,3.3f,z),side<0?-90:90);Marker("room_"+side+"_"+row,new Vector3(side*9,0,z));
