  static void PatchShop(){string path=R+"Resources/Worlds/NorthPointShop.prefab";var shop=PrefabUtility.LoadPrefabContents(path);root=shop.transform;try{var laptops=shop.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Laptop -")||t.name=="classic_laptop").ToArray();foreach(var laptop in laptops){if(!laptop||laptop.GetComponentsInChildren<Renderer>().Length==0)continue;var b=BoundsOf(laptop.gameObject);var pos=new Vector3(b.center.x,b.min.y,b.center.z);Computer(pos,0);Object.DestroyImmediate(laptop.gameObject);}var terminal=shop.GetComponentsInChildren<Interaction>(true).FirstOrDefault(i=>i.id=="computer");if(terminal)terminal.transform.position=new Vector3(-9.75f,1.02f,28.1f);foreach(var t in shop.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Lối tối xuống B1").ToArray())Object.DestroyImmediate(t.gameObject);PrefabUtility.SaveAsPrefabAsset(shop,path);}finally{PrefabUtility.UnloadPrefabContents(shop);}}
